import math

def zero_count(arr):
    if len(arr) == 0:
        return float('nan')

    zeroes = sum(1 for x in arr if x == 0)
    non_zeroes = sum(1 for x in arr if x != 0)
    total = zeroes + non_zeroes

    ratio = zeroes / total
    return ratio

assert math.isclose(zero_count([0, 1, 2, -1, -5, 6, 0, -3, -2, 3, 4, 6, 8]), 0.181818, rel_tol=0.001)

